BEGIN
 IF lf_ops.nucleo_param_valor_v1('CLIENT.TRUST_VARIANT_A_MIN_PARTNERS') IS NULL OR NOT EXISTS (SELECT 1 FROM lf_ops.nucleo_parametros WHERE scope='CLIENT' AND config_key='TRUST_VARIANT_A_MIN_PARTNERS' AND hecho='an_a_min_count') THEN RAISE EXCEPTION 'S22AN_PARAM_PREFLIGHT CLIENT.TRUST_VARIANT_A_MIN_PARTNERS'; END IF;
 IF lf_ops.nucleo_param_valor_v1('CLIENT.TRUST_VARIANT_A_MAX_PARTNERS') IS NULL OR NOT EXISTS (SELECT 1 FROM lf_ops.nucleo_parametros WHERE scope='CLIENT' AND config_key='TRUST_VARIANT_A_MAX_PARTNERS' AND hecho='an_a_max_count') THEN RAISE EXCEPTION 'S22AN_PARAM_PREFLIGHT CLIENT.TRUST_VARIANT_A_MAX_PARTNERS'; END IF;
 IF lf_ops.nucleo_param_valor_v1('CLIENT.TRUST_VARIANT_B_MIN_PARTNERS') IS NULL OR NOT EXISTS (SELECT 1 FROM lf_ops.nucleo_parametros WHERE scope='CLIENT' AND config_key='TRUST_VARIANT_B_MIN_PARTNERS' AND hecho='an_b_min_count') THEN RAISE EXCEPTION 'S22AN_PARAM_PREFLIGHT CLIENT.TRUST_VARIANT_B_MIN_PARTNERS'; END IF;
 IF lf_ops.nucleo_param_valor_v1('CLIENT.TRUST_VARIANT_B_MAX_OPERATIONAL_VISIBLE') IS NULL OR NOT EXISTS (SELECT 1 FROM lf_ops.nucleo_parametros WHERE scope='CLIENT' AND config_key='TRUST_VARIANT_B_MAX_OPERATIONAL_VISIBLE' AND hecho='an_b_operational_count') THEN RAISE EXCEPTION 'S22AN_PARAM_PREFLIGHT CLIENT.TRUST_VARIANT_B_MAX_OPERATIONAL_VISIBLE'; END IF;
 IF lf_ops.nucleo_param_valor_v1('CLIENT.TRUST_VARIANT_B_MIN_STRATEGIC_FEATURED') IS NULL OR NOT EXISTS (SELECT 1 FROM lf_ops.nucleo_parametros WHERE scope='CLIENT' AND config_key='TRUST_VARIANT_B_MIN_STRATEGIC_FEATURED' AND hecho='an_b_strategic_min_count') THEN RAISE EXCEPTION 'S22AN_PARAM_PREFLIGHT CLIENT.TRUST_VARIANT_B_MIN_STRATEGIC_FEATURED'; END IF;
 IF lf_ops.nucleo_param_valor_v1('CLIENT.TRUST_VARIANT_B_MAX_STRATEGIC_FEATURED') IS NULL OR NOT EXISTS (SELECT 1 FROM lf_ops.nucleo_parametros WHERE scope='CLIENT' AND config_key='TRUST_VARIANT_B_MAX_STRATEGIC_FEATURED' AND hecho='an_b_strategic_max_count') THEN RAISE EXCEPTION 'S22AN_PARAM_PREFLIGHT CLIENT.TRUST_VARIANT_B_MAX_STRATEGIC_FEATURED'; END IF;
 IF lf_ops.nucleo_param_valor_v1('CLIENT.TRUST_VARIANT_C_MIN_VERIFIED_PRESS') IS NULL OR NOT EXISTS (SELECT 1 FROM lf_ops.nucleo_parametros WHERE scope='CLIENT' AND config_key='TRUST_VARIANT_C_MIN_VERIFIED_PRESS' AND hecho='an_c_press_count') THEN RAISE EXCEPTION 'S22AN_PARAM_PREFLIGHT CLIENT.TRUST_VARIANT_C_MIN_VERIFIED_PRESS'; END IF;
 IF lf_ops.nucleo_param_valor_v1('CLIENT.TRUST_VARIANT_C_MAIN_PRESS_COUNT') IS NULL OR NOT EXISTS (SELECT 1 FROM lf_ops.nucleo_parametros WHERE scope='CLIENT' AND config_key='TRUST_VARIANT_C_MAIN_PRESS_COUNT' AND hecho='an_c_main_count') THEN RAISE EXCEPTION 'S22AN_PARAM_PREFLIGHT CLIENT.TRUST_VARIANT_C_MAIN_PRESS_COUNT'; END IF;
 IF lf_ops.nucleo_param_valor_v1('CLIENT.TRUST_VARIANT_C_SECONDARY_PRESS_COUNT') IS NULL OR NOT EXISTS (SELECT 1 FROM lf_ops.nucleo_parametros WHERE scope='CLIENT' AND config_key='TRUST_VARIANT_C_SECONDARY_PRESS_COUNT' AND hecho='an_c_secondary_count') THEN RAISE EXCEPTION 'S22AN_PARAM_PREFLIGHT CLIENT.TRUST_VARIANT_C_SECONDARY_PRESS_COUNT'; END IF;
 FOR p IN SELECT value FROM jsonb_array_elements(packs) LOOP
 a:=p->'paquete'; cd:=p->>'codigo';
 IF EXISTS(WITH RECURSIVE anc AS (SELECT codigo,padre FROM lf_ops.nucleo_nodos WHERE pantalla_id=36 UNION ALL SELECT nn.codigo,nn.padre FROM lf_ops.nucleo_nodos nn JOIN anc z ON nn.codigo=z.padre) SELECT 1 FROM anc WHERE codigo=a->>'alcance') THEN RAISE EXCEPTION 'S22_SCOPE_P36 %',cd; END IF;
 ans:=lf_ops.nucleo_regla_proponer_v1(a,true);
 IF ans->>'resultado' IS DISTINCT FROM 'CANDIDATA' OR (ans->>'version')::int IS DISTINCT FROM 1 THEN RAISE EXCEPTION 'S22AN_PROPOSAL_FAIL % %',cd,ans; END IF;
 ans:=lf_ops.nucleo_regla_evaluar_v1(cd,true);
 h:=lf_ops.nucleo_hash_paquete_v1(cd,1); hashes:=hashes||jsonb_build_object(cd,h);
 FOR t IN SELECT entrada,esperado FROM lf_ops.nucleo_regla_pruebas WHERE regla=cd AND version=1 LOOP
 IF lf_ops.nucleo_eval_v1(a->'condicion',t.entrada) IS DISTINCT FROM t.esperado THEN RAISE EXCEPTION 'S22AN_VECTOR_FAIL %',cd; END IF; END LOOP;
 END LOOP;
 SELECT string_agg(j.key||'='||j.value,',' ORDER BY j.key) INTO hash_all FROM jsonb_each_text(hashes) j;
 RAISE EXCEPTION 'S22AN_HASH_ALL %',hash_all;
END $an$;
COMMIT;
